-- Discover's shelves, eras, popular kits and the finder's ranking: the three leagues too.
create or replace function private.on_discover(c public.kit_clubs)
returns boolean language sql immutable set search_path = '' as $$
  select c.top5 or c.league in ('Swiss Super League', 'Eredivisie', 'Primeira Liga', 'Süper Lig') or (c.league = 'National Teams' and c.featured)
$$;
